package com.example.teaching;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import com.example.teaching.grading.*;
import static com.example.teaching.grading.GradingModels.*;
import com.example.teaching.common.*;
import com.example.teaching.evaluation.*;
import com.example.teaching.integration.AcademicDirectory;
import com.example.teaching.security.*;
import jakarta.persistence.EntityManager;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.transaction.annotation.Transactional;

@SpringBootTest(properties="spring.datasource.url=jdbc:h2:mem:grading-outcome;MODE=MySQL;DB_CLOSE_DELAY=-1") @Transactional
class GradingOutcomeWorkflowTest {
 @Autowired GradingService grading;@Autowired GradingOutcomeService outcomes;@Autowired GradingConversionService conversions;@Autowired EntityManager em;
 @MockitoBean AcademicDirectory academic;@MockitoBean RemoteApi remote;
 LocalDate today=LocalDate.now(BusinessTime.ZONE);AcademicEvaluationContext context;
 void actor(Role role,long account,long profile){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new CurrentUser(account,profile,3L,role,"actor"),null,List.of()));}
 @BeforeEach void setup(){actor(Role.SUPER_ADMIN,30,2);when(academic.schoolClass(9L)).thenReturn(new AcademicDirectory.SchoolClass(9L,3L,2L,7L,"Class"));when(academic.studentsAt(eq(9L),any())).thenReturn(List.of(new AcademicDirectory.Student(11L,"Learner A",101L,"ENROLLMENT"),new AcademicDirectory.Student(12L,"Learner B",102L,"ENROLLMENT")));
  context=new AcademicEvaluationContext(9L,3L,LocalDateTime.now(),List.of(new AcademicEvaluationContext.Learner(101L,11L,"Learner A","STUDYING",List.of(new AcademicEvaluationContext.Period(today.minusMonths(1),null))),new AcademicEvaluationContext.Learner(102L,12L,"Learner B","STUDYING",List.of(new AcademicEvaluationContext.Period(today.minusMonths(1),null)))),List.of(new AcademicEvaluationContext.Session(1L,today.minusDays(1),LocalTime.of(8,0),LocalTime.of(9,0),"COMPLETED")),List.of(new AcademicEvaluationContext.Mark(101L,1L,today.minusDays(1),"PRESENT",false),new AcademicEvaluationContext.Mark(102L,1L,today.minusDays(1),"LATE",false)),new AcademicEvaluationContext.Duration(60,1,60L,60L,0,0,true));
  when(academic.evaluationContext(eq(9L),anyBoolean())).thenAnswer(i->context);when(remote.get(contains("/classes/9/result-source"),eq(GradingOutcomeService.Source.class))).thenReturn(new GradingOutcomeService.Source(null,"token",1));when(remote.get(contains("/enrollments/101/result-source"),eq(GradingOutcomeService.Source.class))).thenReturn(new GradingOutcomeService.Source(9L,"token",1));when(remote.get(contains("/enrollments/102/result-source"),eq(GradingOutcomeService.Source.class))).thenReturn(new GradingOutcomeService.Source(9L,"token",1));
 }
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 void bind(Kind kind){grading.assign(9L,new Assignment(kind+"-v1",0L,"Apply class scheme"));actor(Role.TEACHER,10,2);}
 ActivityView activity(String name,String...codes){return grading.create(9L,new ActivityCommand(name,today,List.of(codes)));}
 void fill(ActivityView a,String value){var records=new ArrayList<Mark>();for(long student:new long[]{11,12})for(var code:a.components())records.add(new Mark(student,code,null,Status.GRADED,new BigDecimal(value),null,null));grading.save(9L,a.id(),new SaveMarks(records,"Enter original marks"));}
 void internal(){bind(Kind.INTERNAL);for(var code:List.of("HOMEWORK","QUIZ","MIDTERM","FINAL"))fill(activity(code,code),"7");}
 GradingOutcomeService.Command command(){var p=outcomes.preview(9L);return new GradingOutcomeService.Command(UUID.randomUUID(),p.workflow().revision(),p.fingerprint(),"Reviewed results with source proof");}
 void action(GradingOutcomeService.Action a){outcomes.action(9L,a,command());}
 void publish(){action(GradingOutcomeService.Action.SUBMIT);actor(Role.ADMIN,20,2);action(GradingOutcomeService.Action.APPROVE);action(GradingOutcomeService.Action.PUBLISH);}
 @Test void weightedInternalScoresAndAttendanceAreSeparate(){internal();var row=outcomes.preview(9L).report().students().getFirst();assertEquals(0,new BigDecimal("70").compareTo(row.score()));assertEquals("PASS",row.academicStatus());assertEquals("PASS",row.completionStatus());}
 @Test void missingRequiredComponentIsNotZeroOrPass(){bind(Kind.INTERNAL);fill(activity("Final","FINAL"),"9");var row=outcomes.preview(9L).report().students().getFirst();assertNull(row.score());assertEquals("INSUFFICIENT",row.academicStatus());}
 @Test void attendanceCanBlockCompletionWithoutChangingScore(){internal();context=new AcademicEvaluationContext(context.classId(),context.branchId(),context.observedAt(),context.enrollments(),context.sessions(),List.of(new AcademicEvaluationContext.Mark(101L,1L,today.minusDays(1),"ABSENT",true),context.attendance().getLast()),context.duration());var row=outcomes.preview(9L).report().students().getFirst();assertEquals("PASS",row.academicStatus());assertEquals("ATTENDANCE_NOT_MET",row.completionStatus());assertEquals(0,new BigDecimal("70").compareTo(row.score()));}
 @Test void unfinishedDurationIsNotCompleted(){internal();context=new AcademicEvaluationContext(context.classId(),context.branchId(),context.observedAt(),context.enrollments(),context.sessions(),context.attendance(),new AcademicEvaluationContext.Duration(120,1,60L,120L,0,1,false));assertEquals("IN_PROGRESS",outcomes.preview(9L).report().students().getFirst().completionStatus());}
 @Test void multipleAssessmentsMeanWithinComponent(){internal();fill(activity("Extra homework","HOMEWORK"),"9");assertEquals(0,new BigDecimal("71").compareTo(outcomes.preview(9L).report().students().getFirst().score()));}
 @Test void retakeReplacesOriginalWithoutDoubleWeight(){internal();var root=grading.activities(9L).stream().filter(a->a.components().contains("FINAL")).findFirst().orElseThrow();var retake=grading.create(9L,new ActivityCommand("Retake",today,List.of("FINAL"),root.id(),null,List.of(11L)));grading.save(9L,retake.id(),new SaveMarks(List.of(new Mark(11L,"FINAL",null,Status.GRADED,BigDecimal.valueOf(9),null,null)),"Retake result"));assertEquals(0,new BigDecimal("78").compareTo(outcomes.preview(9L).report().students().getFirst().score()));assertEquals(0,new BigDecimal("70").compareTo(outcomes.preview(9L).report().students().getLast().score()));}
 @Test void ieltsOverallQuarterAndThreeQuarterRoundUp(){assertEquals(0,new BigDecimal("6").compareTo(GradingCalculation.ieltsOverall(List.of(new BigDecimal("6"),new BigDecimal("6"),new BigDecimal("5.5"),new BigDecimal("5.5")))));assertEquals(0,new BigDecimal("6.5").compareTo(GradingCalculation.ieltsOverall(List.of(new BigDecimal("6"),new BigDecimal("6"),new BigDecimal("6.5"),new BigDecimal("6.5")))));}
 @Test void partialIeltsSkillsCannotBeCombinedIntoOverall(){bind(Kind.IELTS);fill(activity("Part 1","LISTENING","READING"),"6");fill(activity("Part 2","WRITING","SPEAKING"),"6");assertNull(outcomes.preview(9L).report().students().getFirst().score());}
 @Test void completeIeltsMockReturnsBand(){bind(Kind.IELTS);fill(activity("Full mock","LISTENING","READING","WRITING","SPEAKING"),"6.5");assertEquals(0,new BigDecimal("6.5").compareTo(outcomes.preview(9L).report().students().getFirst().score()));assertEquals("RECORDED",outcomes.preview(9L).report().students().getFirst().academicStatus());}
 @Test void toeicFullMockReturnsSum(){bind(Kind.TOEIC_LR);fill(activity("Full mock","LISTENING","READING"),"300");assertEquals(0,new BigDecimal("600").compareTo(outcomes.preview(9L).report().students().getFirst().score()));}
 @Test void draftsAndApprovalAreNeverVisibleToStudent(){internal();actor(Role.STUDENT,40,11);assertEquals("PENDING",outcomes.student(101L).state());actor(Role.TEACHER,10,2);action(GradingOutcomeService.Action.SUBMIT);actor(Role.ADMIN,20,2);action(GradingOutcomeService.Action.APPROVE);actor(Role.STUDENT,40,11);assertNull(outcomes.student(101L).result());}
 @Test void submitterCannotApproveOwnSubmission(){internal();actor(Role.ADMIN,20,2);action(GradingOutcomeService.Action.SUBMIT);assertThrows(ApiException.class,()->action(GradingOutcomeService.Action.APPROVE));}
 @Test void noPublishBeforeApproval(){internal();actor(Role.ADMIN,20,2);assertThrows(ApiException.class,()->action(GradingOutcomeService.Action.PUBLISH));}
 @Test void submissionFreezesMarksUntilReturned(){internal();action(GradingOutcomeService.Action.SUBMIT);var a=grading.activities(9L).getFirst();assertThrows(ApiException.class,()->grading.save(9L,a.id(),new SaveMarks(List.of(new Mark(11L,a.components().getFirst(),0L,Status.GRADED,BigDecimal.TEN,null,null)),"Frozen correction")));actor(Role.ADMIN,20,2);action(GradingOutcomeService.Action.REJECT);assertEquals("REJECTED",outcomes.preview(9L).workflow().state());}
 @Test void publishedSnapshotOwnStudentOnlyAndRetractionHidesIt(){internal();publish();actor(Role.STUDENT,40,11);assertEquals(11L,outcomes.student(101L).result().studentId());assertNull(outcomes.student(102L).result());actor(Role.ADMIN,20,2);action(GradingOutcomeService.Action.RETRACT);actor(Role.STUDENT,40,11);assertNull(outcomes.student(101L).result());}
 @Test void academicChangesRequireNewReview(){internal();action(GradingOutcomeService.Action.SUBMIT);when(remote.get(contains("/classes/9/result-source"),eq(GradingOutcomeService.Source.class))).thenReturn(new GradingOutcomeService.Source(null,"token",2));actor(Role.ADMIN,20,2);assertTrue(outcomes.preview(9L).workflow().sourceChanged());assertThrows(ApiException.class,()->action(GradingOutcomeService.Action.APPROVE));}
 @Test void requestReplayDoesNotDuplicateRelease(){internal();var c=command();outcomes.action(9L,GradingOutcomeService.Action.SUBMIT,c);outcomes.action(9L,GradingOutcomeService.Action.SUBMIT,c);assertEquals(1,outcomes.history(9L).size());assertThrows(ApiException.class,()->outcomes.action(9L,GradingOutcomeService.Action.SUBMIT,new GradingOutcomeService.Command(c.requestId(),c.expectedRevision(),c.fingerprint(),"Different reason")));}
 @Test void convertedRawScoreRetainsTableVersion(){var mapping=java.util.stream.IntStream.rangeClosed(0,100).mapToObj(i->Math.min(495,5+5*i)).toList();var table=conversions.create(new GradingConversionService.Command("SYNTHETIC_TEST",0L,"Synthetic mapping","Test fixture, not an official table",new GradingConversionService.Mapping(mapping,mapping)));bind(Kind.TOEIC_LR);var a=grading.create(9L,new ActivityCommand("Raw mock",today,List.of("LISTENING","READING"),null,table.id(),null));var sheet=grading.save(9L,a.id(),new SaveMarks(List.of(new Mark(11L,"LISTENING",null,Status.GRADED,null,null,null,60)),"Convert synthetic raw mark"));var m=sheet.records().getFirst();assertEquals(60,m.rawScore());assertEquals(0,new BigDecimal("305").compareTo(m.score()));assertEquals(table.id(),m.conversionId());}
 @Test void rawScoresWithoutConversionAreRejected(){bind(Kind.TOEIC_LR);var a=activity("No table","LISTENING");assertThrows(ApiException.class,()->grading.save(9L,a.id(),new SaveMarks(List.of(new Mark(11L,"LISTENING",null,Status.GRADED,null,null,null,60)),"Missing mapping")));}
 @Test void futureMockDoesNotEraseCompletedMock(){bind(Kind.IELTS);fill(activity("Completed","LISTENING","READING","WRITING","SPEAKING"),"6");grading.create(9L,new ActivityCommand("Future mock",today.plusDays(5),List.of("LISTENING","READING","WRITING","SPEAKING")));assertEquals(0,new BigDecimal("6").compareTo(outcomes.preview(9L).report().students().getFirst().score()));}
 @Test void exemptionsAreExcludedAndRemainingWeightsNormalized(){internal();var a=grading.activities(9L).stream().filter(x->x.components().contains("FINAL")).findFirst().orElseThrow();grading.save(9L,a.id(),new SaveMarks(List.of(new Mark(11L,"FINAL",0L,Status.EXEMPT,null,null,"Approved exemption")),"Exempt final"));assertEquals(0,new BigDecimal("70").compareTo(outcomes.preview(9L).report().students().getFirst().score()));}
 @Test void absentRetakeDoesNotDeleteOriginalGrade(){internal();var a=grading.activities(9L).stream().filter(x->x.components().contains("FINAL")).findFirst().orElseThrow();var retake=grading.create(9L,new ActivityCommand("Retake",today,List.of("FINAL"),a.id(),null,List.of(11L)));grading.save(9L,retake.id(),new SaveMarks(List.of(new Mark(11L,"FINAL",null,Status.ABSENT,null,null,"Did not attend retake")),"Record retake absence"));assertEquals(0,new BigDecimal("70").compareTo(outcomes.preview(9L).report().students().getFirst().score()));}
 @Test void reopeningPublicationHidesSnapshotAndAllowsNewDraft(){internal();publish();action(GradingOutcomeService.Action.REOPEN);actor(Role.STUDENT,40,11);assertNull(outcomes.student(101L).result());actor(Role.TEACHER,10,2);var a=grading.activities(9L).getFirst();grading.save(9L,a.id(),new SaveMarks(List.of(new Mark(11L,a.components().getFirst(),0L,Status.GRADED,BigDecimal.valueOf(8),null,null)),"Correct reopened draft"));assertEquals("DRAFT",outcomes.preview(9L).workflow().state());}
 @Test void teacherCannotApproveOrRetract(){internal();action(GradingOutcomeService.Action.SUBMIT);assertThrows(ApiException.class,()->action(GradingOutcomeService.Action.APPROVE));assertThrows(ApiException.class,()->action(GradingOutcomeService.Action.RETRACT));}
 @Test void conversionRequiresCompleteMonotonicTable(){assertThrows(ApiException.class,()->conversions.create(new GradingConversionService.Command("INVALID",0L,"Invalid","Incomplete mapping",new GradingConversionService.Mapping(List.of(5,10),List.of(5,10)))));}
}
